package com.hrcoresystem.hrcore_api.modules.tenant.employeefiles.infrastructure.api;
import com.hrcoresystem.hrcore_api.common.response.ApiResponse; import com.hrcoresystem.hrcore_api.modules.tenant.employeefiles.application.dto.*; import com.hrcoresystem.hrcore_api.modules.tenant.employeefiles.application.service.*; import com.hrcoresystem.hrcore_api.modules.tenant.employeefiles.domain.model.*; import com.hrcoresystem.hrcore_api.modules.tenant.employees.application.service.CurrentEmployeeResolver; import java.nio.charset.StandardCharsets; import java.nio.file.Files; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;
@RestController @RequestMapping("/api/me/documents") public class MyDocumentController {
 private final CurrentEmployeeResolver current; private final EmployeeFileManagementService files; private final EmployeeDocumentManagementService documents; private final DocumentVersionService versions;
 public MyDocumentController(CurrentEmployeeResolver c,EmployeeFileManagementService f,EmployeeDocumentManagementService d,DocumentVersionService v){current=c;files=f;documents=d;versions=v;}
 @GetMapping @PreAuthorize("isAuthenticated()") public ApiResponse<Page<DocumentResponse>> list(@PageableDefault(size=25) Pageable page){var employee=current.require();var file=files.byEmployee(employee.id());return ApiResponse.success("Documentos propios consultados correctamente",documents.list(file.id(),new EmployeeDocumentFilter(null,FileStatus.ACTIVE,null,false),page));}
 @GetMapping("/{documentId}/versions/{versionId}/download") @PreAuthorize("isAuthenticated()") public ResponseEntity<StreamingResponseBody> download(@PathVariable UUID documentId,@PathVariable UUID versionId){var employee=current.require();var file=files.byEmployee(employee.id());var result=versions.prepareDownload(file.id(),documentId,versionId);StreamingResponseBody body=out->{try{Files.copy(result.path(),out);}finally{result.cleanup();}};return ResponseEntity.ok().contentType(MediaType.parseMediaType(result.mimeType())).contentLength(result.size()).cacheControl(CacheControl.noStore()).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(result.filename(),StandardCharsets.UTF_8).build().toString()).header("X-Content-Type-Options","nosniff").body(body);}
}
